    {
      "step": 1,
      "text": "{{ing_01|ROSE PETALS}}, the lower white part removed, sewed into a linen bag and immersed in {{ing_02|wine}} for seven days."
    },
    {
      "step": 2,
      "text": "Thereupon add a sack of {{ing_01|new petals}} which allow to draw for another seven days."
    },
    {
      "step": 3,
      "text": "Again remove the {{ing_01|old petals}} and replace them by {{ing_01|fresh ones}} for another week; then strain the {{ing_02|wine}} through the colander."
    },
    {
      "step": 4,
      "text": "Before serving, add {{ing_03|honey}} sweetening to taste."
    },
    {
      "step": 5,
      "text": "Take care that only the best {{ing_01|petals}} free from dew be used for soaking."
    }
